-- One slot. Draft only.
BEGIN;
-- PT103-S2-Q1
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND q.stimulus=$batch01$Insurance that was to become effective at 9 A.M.on a certain date was taken out on the life of a flight attendant. He died on that date at 10 A.M.local time, which was two hours before 9 A.M.in the time zone where the policy had been purchased. The insurance company contended that the policy had not become effective; a representative of the flight attendant’s beneficiary, his mother, countered by arguing that the policy amount should be paid because the attendant had been his mother’s sole support, and she was ill.$batch01$ AND q.prompt=$batch01$The representative's argument is flawed as a counter to the insurance company's contention because$batch01$ AND q.correct_choice=$batch01$B$batch01$) THEN RAISE EXCEPTION 'Question changed: PT103-S2-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S2-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$the conclusion is no more than a paraphrase of the evidence offered in support of it$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q1 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$it appeals to the emotion of pity rather than addressing the issue raised$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q1 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$it makes an unwarranted distinction between family obligations and business obligations$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q1 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$it substitutes an attack on a person for the giving of reasons$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q1 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$a cause and its effect are mistaken for each other$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q1 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT103-S2-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Issue$batch01$, $batch01$Did the policy become effective before the attendant died? The local clock read 10 A.M., but that was before 9 A.M. in the purchase time zone.$batch01$), (1, $batch01$Representative's conclusion$batch01$, $batch01$The insurer should pay the mother.$batch01$), (2, $batch01$Evidence$batch01$, $batch01$The attendant was her sole support and she is ill.$batch01$), (3, $batch01$Evaluate$batch01$, $batch01$Those facts make her loss especially hard. Do they settle what the policy's effective time means? No. The representative needs an argument about the contract's time zone or wording. A sympathetic beneficiary can still hold a policy that had not begun.$batch01$), (4, $batch01$Goal$batch01$, $batch01$Find the appeal to pity in place of a response to the coverage issue.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The mother's illness and dependence are not a paraphrase of “the policy should pay.” They are distinct facts, albeit irrelevant to the contract timing.$batch01$), ($batch01$B$batch01$, $batch01$Pity for the mother is understandable, but it does not answer the insurer's contention about when coverage began. The argument swaps an emotional reason to want payment for a reason the contract requires it.$batch01$), ($batch01$C$batch01$, $batch01$The representative makes no comparison between family obligations and business obligations. The defect is that family hardship does not determine the insurance contract.$batch01$), ($batch01$D$batch01$, $batch01$No person is attacked. The representative invites sympathy for the mother.$batch01$), ($batch01$E$batch01$, $batch01$No cause-and-effect relationship is reversed. The dispute is over the time at which a policy took effect.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT103-S2-Q1$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
